//! The `dump` command-line tool: reads binary data (file or stdin)
//! and prints it in human-readable form (hex dump, bit string,
//! and/or run-length analysis).
//!
//! Usage: `dump [--bits] [--runs] [<file>|-""]`
//!
//! The default output is a hex dump in the style of `xxd` (address,
//! 16 hex bytes per line, ASCII representation). Optional flags:
//!
//! * `--bits` - additionally print the bit string (0/1, MSB first)
//! * `--runs` - additionally print the run-length analysis
//! * `-` or no argument - read from stdin

use std::env;
use std::fs;
use std::io::Read;
use std::process::ExitCode;

use bit_sequences::deviation::deviation_score;
use bit_sequences::one_step_test::RunFrequencyCounter;
use bit_sequences::one_step_test::cumulated_distribution_from_histogram;

/// Entry point: reads binary data and prints it human-readably.
fn main() -> ExitCode {
    // The command-line arguments without the program name.
    let arguments: Vec<String> = env::args().skip(1).collect();
    // Whether the bit string should be printed additionally.
    let mut show_bits = false;
    // Whether the run-length analysis should be printed additionally.
    let mut show_runs = false;
    // The input path; empty means stdin.
    let mut input_path = String::new();
    // Examine every argument in turn.
    for argument in arguments.iter() {
        // The flag enables the bit string output.
        if argument == "--bits" {
            show_bits = true;
            continue;
        }
        // The flag enables the run-length analysis output.
        if argument == "--runs" {
            show_runs = true;
            continue;
        }
        // Everything else is the input path (or `-` for stdin).
        input_path = argument.clone();
    }
    // Read the input data (file or stdin).
    let data = match read_input(&input_path) {
        Ok(bytes) => bytes,
        Err(message) => {
            eprintln!("{message}");
            return ExitCode::FAILURE;
        }
    };
    // Early exit: empty input has nothing to dump.
    if data.is_empty() {
        eprintln!("Input is empty.");
        return ExitCode::FAILURE;
    }
    // Always print the hex dump.
    print_hex_dump(&data);
    // Optionally print the bit string.
    if show_bits {
        print_bit_string(&data);
    }
    // Optionally print the run-length analysis.
    if show_runs {
        print_run_analysis(&data);
    }
    // Terminate successfully.
    ExitCode::SUCCESS
}

/// Reads the input: a named file, `-` for stdin, or stdin if no
/// path is given.
fn read_input(path: &str) -> Result<Vec<u8>, String> {
    // Early exit: empty path or `-` means read from stdin.
    if path.is_empty() || path == "-" {
        let mut buffer = Vec::new();
        std::io::stdin()
            .read_to_end(&mut buffer)
            .map_err(|e| format!("Error reading stdin: {e}"))?;
        return Ok(buffer);
    }
    fs::read(path).map_err(|e| format!("Error reading {path}: {e}"))
}

/// Prints a hex dump in the style of `xxd`: 16 bytes per line with
/// address, hex representation, and ASCII art.
fn print_hex_dump(data: &[u8]) {
    // The total number of bytes.
    let total = data.len();
    // Print a header line.
    println!("Hex dump ({} bytes):", total);
    // Print each line of 16 bytes.
    for (line_index, line) in data.chunks(16).enumerate() {
        // The starting address of this line.
        let address = line_index * 16;
        // The hex representation of the line.
        let mut hex_part = String::new();
        // The ASCII representation of the line.
        let mut ascii_part = String::new();
        // Consider all 16 positions (even beyond the line length).
        for position in 0..16 {
            // Pad with spaces beyond the actual data.
            if position < line.len() {
                // Format the byte as two hex digits.
                hex_part.push_str(&format!("{:02x} ", line[position]));
                // Add the ASCII character if printable, a dot otherwise.
                let byte = line[position];
                if byte >= 0x20 && byte < 0x7f {
                    ascii_part.push(byte as char);
                } else {
                    ascii_part.push('.');
                }
            } else {
                // Pad the hex part with spaces for alignment.
                hex_part.push_str("   ");
                // Pad the ASCII part with a space.
                ascii_part.push(' ');
            }
            // Add a space after 8 bytes for readability.
            if position == 7 {
                hex_part.push(' ');
            }
        }
        // Print the line: address, hex, ASCII.
        println!("  {:08x}: {} |{}|", address, hex_part, ascii_part);
    }
    // Print a blank line after the dump.
    println!();
}

/// Prints the bit string of the data (MSB first per byte).
fn print_bit_string(data: &[u8]) {
    // The total number of bits.
    let total_bits = data.len() * 8;
    // Print a header line.
    println!("Bit string ({} bits, MSB first):", total_bits);
    // Consider each byte.
    for &byte in data.iter() {
        // Print all eight bits, MSB first.
        for bit_position in (0..8).rev() {
            // Print the bit at the current position.
            print!("{}", (byte >> bit_position) & 1);
        }
        // Print a space between bytes for readability.
        print!(" ");
    }
    // End the line.
    println!();
    // Print a blank line after the bit string.
    println!();
}

/// Prints the run-length analysis of the data: the cumulated
/// distribution and the deviation score.
fn print_run_analysis(data: &[u8]) {
    // Create a fresh run frequency counter.
    let mut counter = RunFrequencyCounter::new();
    // Feed the data into the counter.
    counter.process_bytes(data);
    // Finalize the sequence.
    counter.finalize();
    // The number of bits M.
    let bit_count = counter.byte_count() * 8;
    // The cumulated distribution.
    let cumulated = cumulated_distribution_from_histogram(counter.histogram());
    // The deviation score.
    let score = deviation_score(counter.histogram());
    // Print a header line.
    println!("Run-length analysis ({} bits):", bit_count);
    // Print the deviation score.
    println!("  Deviation score: {score:.3} (1.0 = ideal, higher = structured)");
    // Print the cumulated distribution (first 20 entries).
    print!("  l_n: [");
    // Consider the first 20 entries or fewer.
    for (position, &value) in cumulated.iter().enumerate().take(20) {
        // Print a comma before all but the first entry.
        if position > 0 {
            print!(", ");
        }
        // Print the value.
        print!("{value}");
    }
    // Close the bracket.
    println!("]");
    // Print the expected distribution for comparison.
    print!("  expected: [");
    // Consider the first 20 entries or fewer.
    for position in 1..=cumulated.len().min(20) {
        // Print a comma before all but the first entry.
        if position > 1 {
            print!(", ");
        }
        // Print the expected value.
        print!("{}", (bit_count as f64 / 2f64.powi(position as i32 - 1)) as u64);
    }
    // Close the bracket.
    println!("]");
    // Print a blank line after the analysis.
    println!();
}
